#include <stdio.h>
#include <math.h>

#define W 2400
#define H 1800

int main(void){
    FILE*f=fopen("reconstructed.ppm","w");
    fprintf(f,"P3\n%d %d\n255\n",W,H);
    float vw=2.0f*W/H, vh=2.0f;
    float O[3]={0,0,0};
    float ll[3]={-vw/2,-vh/2,-1.0f};
    float hor[3]={vw,0,0}, ver[3]={0,vh,0};
    float cen[3]={0,-0.5f,-5.0f};
    float rad=1.0f, py=-1.5f;
    float L=1.0f/sqrtf(3.0f);
    float light[3]={L,L,-L};
    for(int y=0;y<H;y++){
        float v=(float)y/(H-1);
        for(int x=0;x<W;x++){
            float u=(float)x/(W-1);
            float tgx=ll[0]+u*hor[0]+(1-v)*ver[0];
            float tgy=ll[1]+u*hor[1]+(1-v)*ver[1];
            float tgz=ll[2]+u*hor[2]+(1-v)*ver[2];
            float rl=sqrtf(tgx*tgx+tgy*tgy+tgz*tgz);
            float dx=tgx/rl,dy=tgy/rl,dz=tgz/rl;
            /* sphere */
            float ocx=O[0]-cen[0],ocy=O[1]-cen[1],ocz=O[2]-cen[2];
            float a=dx*dx+dy*dy+dz*dz;
            float b=2*(ocx*dx+ocy*dy+ocz*dz);
            float cc=ocx*ocx+ocy*ocy+ocz*ocz-rad*rad;
            float dis=b*b-4*a*cc;
            int hs=0,ht=-1; float t=0,nx=0,ny=0,nz=0;
            if(dis>0){
                float s=sqrtf(dis);
                float t1=(-b-s)/(2*a);
                if(t1<0.001f)t1=(-b+s)/(2*a);
                if(t1>=0.001f){
                    hs=1;t=t1;
                    float px=O[0]+t1*dx,pyy=O[1]+t1*dy,pz=O[2]+t1*dz;
                    nx=px-cen[0];ny=pyy-cen[1];nz=pz-cen[2];
                    float nl=sqrtf(nx*nx+ny*ny+nz*nz);
                    nx/=nl;ny/=nl;nz/=nl;
                }
            }
            /* plane */
            int hp=0; float tp=0;
            if(fabsf(dy)>=0.0001f){ tp=(py-O[1])/dy; if(tp>=0.001f)hp=1; }
            if(hs&&(!hp||t<tp)){ ht=1; }
            else if(hp){ ht=0; t=tp; nx=0;ny=1;nz=0; }
            float r,g,bl;
            if(ht<0){
                float t2=0.5f*(dy+1.0f);
                r=1-t2+t2*0.5f; g=1-t2+t2*0.7f; bl=1-t2+t2*1.0f;
            }else{
                float px=O[0]+t*dx,pyy=O[1]+t*dy,pz=O[2]+t*dz;
                float dif=nx*light[0]+ny*light[1]+nz*light[2];
                if(dif<0)dif=0;
                float sox=px+nx*0.001f,soy=pyy+ny*0.001f,soz=pz+nz*0.001f;
                float ox=sox-cen[0],oy=soy-cen[1],oz=soz-cen[2];
                float a3=light[0]*light[0]+light[1]*light[1]+light[2]*light[2];
                float b3=2*(ox*light[0]+oy*light[1]+oz*light[2]);
                float c3=ox*ox+oy*oy+oz*oz-rad*rad;
                float d3=b3*b3-4*a3*c3;
                if(d3>0){
                    float s3=sqrtf(d3);
                    float t3=(-b3-s3)/(2*a3);
                    if(t3<0.001f)t3=(-b3+s3)/(2*a3);
                    if(t3>=0.001f)dif=0;
                }
                float inten=0.2f+0.8f*dif;
                float alx,aly,alz;
                if(ht==1){ alx=1.0f;aly=0.2f;alz=0.2f; }
                else{
                    int val=(int)(floorf(px)+floorf(pz));
                    if((val&1)==0){alx=0.9f;aly=0.9f;alz=0.9f;}
                    else{alx=0.4f;aly=0.4f;alz=0.4f;}
                }
                r=alx*inten;g=aly*inten;bl=alz*inten;
            }
            if(r<0)r=0;if(r>1)r=1;
            if(g<0)g=0;if(g>1)g=1;
            if(bl<0)bl=0;if(bl>1)bl=1;
            fprintf(f,"%d %d %d\n",(int)(r*255.99f),(int)(g*255.99f),(int)(bl*255.99f));
        }
    }
    fclose(f);
    return 0;
}

